CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE users ALTER COLUMN email DROP NOT NULL;
ALTER TABLE users ADD COLUMN IF NOT EXISTS role TEXT NOT NULL DEFAULT 'customer';
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN IF NOT EXISTS active BOOLEAN NOT NULL DEFAULT true;
CREATE UNIQUE INDEX IF NOT EXISTS users_phone_unique ON users(phone) WHERE phone IS NOT NULL;
CREATE TABLE IF NOT EXISTS garages(id SERIAL PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL,open_hour INT NOT NULL DEFAULT 8,close_hour INT NOT NULL DEFAULT 17,capacity INT NOT NULL DEFAULT 3,cancel_hours INT NOT NULL DEFAULT 2,reminder_hours INT NOT NULL DEFAULT 24,notification_template TEXT NOT NULL DEFAULT 'Lịch bảo dưỡng của bạn đã được cập nhật',active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS services(id SERIAL PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price INT NOT NULL CHECK(price>=0),duration INT NOT NULL CHECK(duration>0),checklist JSONB NOT NULL DEFAULT '[]',active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS vehicles(id SERIAL PRIMARY KEY,owner_id INT NOT NULL REFERENCES users(id),plate TEXT NOT NULL UNIQUE,brand TEXT NOT NULL,model TEXT NOT NULL,year INT NOT NULL,odometer INT NOT NULL CHECK(odometer>=0));
CREATE TABLE IF NOT EXISTS appointments(id SERIAL PRIMARY KEY,customer_id INT NOT NULL REFERENCES users(id),vehicle_id INT NOT NULL REFERENCES vehicles(id),garage_id INT NOT NULL REFERENCES garages(id),starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL DEFAULT 'pending',services JSONB NOT NULL,checklist JSONB NOT NULL DEFAULT '[]',technician_id INT REFERENCES users(id),notes TEXT NOT NULL DEFAULT '',condition TEXT NOT NULL DEFAULT '',reason TEXT NOT NULL DEFAULT '',proposed_at TIMESTAMPTZ,paid BOOLEAN NOT NULL DEFAULT false,total INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,reminded_for TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS appointments_slot ON appointments(garage_id,starts_at,ends_at);
CREATE TABLE IF NOT EXISTS extras(id SERIAL PRIMARY KEY,appointment_id INT NOT NULL REFERENCES appointments(id),description TEXT NOT NULL,amount INT NOT NULL CHECK(amount>=0),status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS photos(id SERIAL PRIMARY KEY,appointment_id INT NOT NULL REFERENCES appointments(id),kind TEXT NOT NULL,data TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews(id SERIAL PRIMARY KEY,appointment_id INT NOT NULL UNIQUE REFERENCES appointments(id),rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id SERIAL PRIMARY KEY,user_id INT NOT NULL REFERENCES users(id),appointment_id INT REFERENCES appointments(id),message TEXT NOT NULL,read BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS events(id SERIAL PRIMARY KEY,appointment_id INT NOT NULL REFERENCES appointments(id),actor_id INT REFERENCES users(id),action TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id INT NOT NULL REFERENCES users(id),expires_at TIMESTAMPTZ NOT NULL);
